option.value:
/* Header styles - responsive improvements */
:host {
  display: block;
  position: relative;
  z-index: 50;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #008f4d;
  color: #ffffff;
  padding: 0 clamp(16px, 2vw, 32px);
  height: 32px;
  font-size: 16px;
}

.contact-line,
.utility-nav,
.primary-nav {
  display: flex;
  align-items: center;
}

.contact-line { gap: 8px; }
.utility-nav { gap: 22px; }
.utility-nav a { color: inherit; text-decoration: none; }

.main-nav {
  display: grid;
  grid-template-columns: 220px 1fr 112px;
  align-items: center;
  background: #ffffff;
  padding: 0 clamp(16px, 2vw, 32px);
  height: 76px;
  position: relative;
  z-index: 60;
}

.brand { display: inline-flex; align-items: center; gap: 8px; color: #01884e; font-weight: 800; }
.brand img { height: 34px; width: 30px; object-fit: contain; }

/* Primary nav */
.primary-nav {
  display: flex;
  gap: clamp(12px, 2vw, 28px);
  justify-content: center;
  align-items: center;
  color: #444;
  font-size: clamp(16px, 1.45vw, 20px);
  font-weight: 400;
}

.nav-link { display: inline-flex; align-items: center; gap: 12px; color: inherit; text-decoration: none; padding: 6px 4px; }
.nav-link:hover, .nav-link.active, .nav-item:focus-within > .nav-link, .nav-item:hover > .nav-link { color: #01884e; }

.nav-item { position: relative; }
.chevron { width: 10px; height: 10px; display: inline-block; transform: rotate(45deg); border-right: 2px solid currentColor; border-bottom: 2px solid currentColor; margin-left: 6px; }

/* Dropdown */
.dropdown-menu {
  position: absolute;
  top: calc(100% + 10px);
  left: 0;
  min-width: 320px;
  max-width: min(90vw, 700px);
  background: #fff;
  border-radius: 18px;
  box-shadow: 0 20px 45px rgba(0,0,0,0.12);
  padding: 28px 20px;
  display: flex;
  flex-direction: column;
  gap: 18px;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity .16s ease, visibility .16s ease;
  z-index: 100;
}

.nav-item:focus-within > .dropdown-menu,
.nav-item:hover > .dropdown-menu {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.dropdown-link {
  display: block;
  color: #2c2c2c;
  font-size: 18px;
  padding: 8px 14px 18px;
  text-decoration: none;
  position: relative;
}
.dropdown-link::after { content: ""; position: absolute; left: 14px; bottom: 8px; width: 46px; height: 3px; background: #f9ce31; }
.dropdown-link.highlighted { background: #fffaf0; border-radius: 8px; padding-top: 14px; padding-bottom: 26px; }

.nav-cta { display: inline-flex; align-items: center; justify-content: center; background: #f9ce31; color: #141414; border-radius: 999px; padding: 0 22px; height: 38px; font-weight: 800; text-decoration: none; }

/* Responsive adjustments */
@media (max-width: 1180px) {
  .main-nav { grid-template-columns: 1fr; gap: 8px; height: auto; padding-top: 18px; padding-bottom: 18px; }
  .brand { justify-self: start; }
  .primary-nav { justify-content: center; flex-wrap: wrap; gap: 12px 20px; }
  /* Center dropdown under the page for mid screens */
  .dropdown-menu { left: 50%; transform: translateX(-50%); top: calc(100% + 12px); min-width: min(84vw, 700px); }
}

@media (max-width: 820px) {
  .primary-nav { gap: 12px; font-size: 16px; }
  .brand img { height: 30px; width: 26px; }
}

@media (max-width: 620px) {
  .topbar { flex-direction: column; align-items: flex-start; gap: 8px; height: auto; padding-top: 12px; padding-bottom: 12px; }
  .main-nav { display: flex; flex-direction: column; gap: 12px; padding-left: 16px; padding-right: 16px; }
  .primary-nav { flex-direction: column; align-items: stretch; justify-content: flex-start; }
  .nav-link { padding: 12px 8px; }
  .dropdown-menu { position: static; width: 100%; transform: none; left: auto; top: auto; box-shadow: 0 12px 30px rgba(0,0,0,0.08); }
  .dropdown-link { padding-left: 12px; padding-right: 12px; font-size: 17px; }
}
